}
"

cd /workspace && node -e "
const XLSX = require('xlsx');
const wb = XLSX.readFile('testbed/data/travel_expenses.xlsx');
const ws = wb.Sheets['Travel'];
const data = XLSX.utils.sheet_to_json(ws);
// Las Vegas hotel
const lvHotels = data.filter(r => r.Type === 'Hotel' && (r['Route/Location'] || '').includes('Las Vegas'));
console.log('=== Las Vegas Hotels ===');
lvHotels.forEach(h => console.log(JSON.stringify(h)));
// Las Vegas car rentals
const lvCars = data.filter(r => r.Type === 'Car Rental' && (r['Route/Location'] || '').includes('Las Vegas'));
console.log('\n=== Las Vegas Car Rentals ===');
lvCars.forEach(c => console.log(JSON.stringify(c)));
"

